<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$db->prepare('INSERT INTO customers(name,phone,address) VALUES(?,?,?)')->execute([trim($_POST['name']),trim($_POST['phone']??''),trim($_POST['address']??'')]);header('Location: customers.php?saved=1');exit;}catch(Throwable $e){$error=$e->getMessage();}} $rows=$db->query("SELECT c.*,COALESCE((SELECT SUM(s.total-s.paid) FROM sales s WHERE s.customer_id=c.id AND s.payment_method='credit'),0) due FROM customers c ORDER BY c.name")->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customers</title><link rel="stylesheet" href="style.css"></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">CUSTOMERS</div><h1>Customers</h1><p>Customer directory and outstanding credit sales.</p></div></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ Customer added.</div><?php endif;?><section class="panel"><h2>Add Customer</h2><form method="post" class="grid"><label>Name<input name="name" required></label><label>Phone<input name="phone"></label><label>Address<input name="address"></label><button class="btn">Save Customer</button></form></section><section class="panel"><table><tr><th>Customer</th><th>Phone</th><th>Address</th><th>Credit Due</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['address'])?></td><td>Rs. <?=money($r['due'])?></td></tr><?php endforeach;?></table></section></main></body></html>